public static AAXPurchReturnOrderCreatedBusinessEventContract newFromPurchTable(PurchTable _purchTable)
{
    var contract = new AAXPurchReturnOrderCreatedBusinessEventContract();
    contract.initialize(_purchTable);

    return contract;
}

